function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's needs 1 to 50000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is between 1 and 1000.';
  return null;
}

