function beautifulSubstrings(s, k) {
  let step = 1;
  while ((step * step) % k !== 0) {
    step++;
  }

  const seen = new Map();
  seen.set('0,0', 1);
  let balance = 0;
  let vowels = 0;
  let count = 0;

  for (const ch of s) {
    if ('aeiou'.includes(ch)) {
      balance++;
      vowels++;
    } else {
      balance--;
    }
    const key = balance + ',' + (vowels % step);
    const matches = seen.get(key) ?? 0;
    count += matches;
    seen.set(key, matches + 1);
  }
  return count;
}

