function beautifulSubstrings(s, k) {
  let total = 0;
  for (let start = 0; start < s.length; start++) {
    let v = 0, c = 0;
    for (let end = start; end < s.length; end++) {
      if (/[aeiou]/.test(s[end])) v++; else c++;
      if (v === c && (v * c) % k === 0) total++;
    }
  }
  return total;
}

