function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const vowels = 'aeiou', consonants = 'bcdfghjklmnpqrstvwxyz';
  const letter = (p) => rand() < p ? vowels[pick(0, 4)] : consonants[pick(0, 20)];
  const friendly = [1, 2, 3, 4, 5, 6, 8, 9, 12, 16, 18, 25, 36, 49, 100, 144];
  if (size === 'large') {
    const n = 10000;
    const k = rand() < 0.6 ? friendly[pick(0, friendly.length - 1)] : pick(1, 1000);
    const p = 0.3 + rand() * 0.4;
    return [Array.from({ length: n }, () => letter(p)).join(''), k];
  }
  const n = pick(1, 14);
  const k = rand() < 0.7 ? pick(1, 9) : pick(1, 1000);
  const p = rand();
  return [Array.from({ length: n }, () => letter(p)).join(''), k];
}
